namespace ET.Server
{
    [FriendOf(typeof(GatePlayerProxy))]
    internal static class OnlineWorldGateHelper
    {
        public static GatePlayerProxy Authenticated(Session session)
        {
            OnlineSessionComponent component = session.GetComponent<OnlineSessionComponent>();
            GatePlayerProxy proxy = component?.Proxy;
            return proxy != null && proxy.IsAuthenticated ? proxy : null;
        }
    }

    [MessageSessionHandler(SceneType.GameGate)] [FriendOf(typeof(OnlineSessionComponent))] [FriendOf(typeof(GatePlayerProxy))]
    public class C2G_EnterWorldHandler: MessageSessionHandler<C2G_EnterWorld,G2C_EnterWorld>
    { protected override async ETTask Run(Session session,C2G_EnterWorld request,G2C_EnterWorld response){if(request.InventorySchemaVersion!=1){response.Error=ErrorCode.ERR_OnlineWorldOperationInvalid;response.Message="客户端库存协议需要更新";return;}GatePlayerProxy p=OnlineWorldGateHelper.Authenticated(session);if(p==null){response.Error=ErrorCode.ERR_OnlineSessionNotLoggedIn;return;}G2P_EnterWorld m=G2P_EnterWorld.Create();m.PlayerId=p.PlayerId;m.SessionEpoch=p.SessionEpoch;m.OperationId=request.OperationId;m.MapId=request.MapId;using P2G_EnterWorld r=await session.Root().GetComponent<MessageSender>().Call(p.PlayerActorId,m,false) as P2G_EnterWorld;response.Error=r.Error;response.Message=r.Message;response.HasWorld=r.HasWorld;response.World=OnlineWorldSnapshotHelper.Clone(r.World);} }

