    [MessageSessionHandler(SceneType.GameGate)] [FriendOf(typeof(OnlineSessionComponent))] [FriendOf(typeof(GatePlayerProxy))]
    public class C2G_ReportWorldTransformHandler: MessageSessionHandler<C2G_ReportWorldTransform,G2C_ReportWorldTransform>
    { protected override async ETTask Run(Session session,C2G_ReportWorldTransform request,G2C_ReportWorldTransform response){GatePlayerProxy p=OnlineWorldGateHelper.Authenticated(session);if(p==null){response.Error=ErrorCode.ERR_OnlineSessionNotLoggedIn;return;}G2P_ReportWorldTransform m=G2P_ReportWorldTransform.Create();m.PlayerId=p.PlayerId;m.SessionEpoch=p.SessionEpoch;m.PositionX=request.PositionX;m.PositionY=request.PositionY;m.PositionZ=request.PositionZ;m.YawDegrees=request.YawDegrees;m.LifecycleRevision=request.LifecycleRevision;using P2G_ReportWorldTransform r=await session.Root().GetComponent<MessageSender>().Call(p.PlayerActorId,m,false) as P2G_ReportWorldTransform;response.Error=r.Error;response.Message=r.Message;response.WorldId=r.WorldId;response.MapId=r.MapId;response.UnitId=r.UnitId;response.StateRevision=r.StateRevision;response.LifecycleRevision=r.LifecycleRevision;} }

    [MessageSessionHandler(SceneType.GameGate)] [FriendOf(typeof(OnlineSessionComponent))] [FriendOf(typeof(GatePlayerProxy))]
    public class C2G_WorldMeleeAttackHandler:MessageSessionHandler<C2G_WorldMeleeAttack,G2C_WorldMeleeAttack>
    {protected override async ETTask Run(Session session,C2G_WorldMeleeAttack q,G2C_WorldMeleeAttack p){GatePlayerProxy a=OnlineWorldGateHelper.Authenticated(session);if(a==null){p.Error=ErrorCode.ERR_OnlineSessionNotLoggedIn;return;}G2P_WorldMeleeAttack m=G2P_WorldMeleeAttack.Create();m.PlayerId=a.PlayerId;m.SessionEpoch=a.SessionEpoch;m.AttackSequence=q.AttackSequence;m.WeaponItemId=q.WeaponItemId;m.AimX=q.AimX;m.AimZ=q.AimZ;m.LifecycleRevision=q.LifecycleRevision;m.AimY=q.AimY;m.OriginX=q.OriginX;m.OriginY=q.OriginY;m.OriginZ=q.OriginZ;m.HasProjectileOrigin=q.HasProjectileOrigin;m.CollisionContentHash=q.CollisionContentHash;using P2G_WorldMeleeAttack r=await session.Root().GetComponent<MessageSender>().Call(a.PlayerActorId,m,false) as P2G_WorldMeleeAttack;p.Error=r.Error;p.Message=r.Message;p.WorldId=r.WorldId;p.UnitId=r.UnitId;p.AttackSequence=r.AttackSequence;p.Accepted=r.Accepted;p.WorldRevision=r.WorldRevision;p.LifecycleRevision=r.LifecycleRevision;}}

    [MessageSessionHandler(SceneType.GameGate)] [FriendOf(typeof(OnlineSessionComponent))] [FriendOf(typeof(GatePlayerProxy))]
    public class C2G_ReportWorldEnemyNavigationHandler:MessageSessionHandler<C2G_ReportWorldEnemyNavigation,G2C_ReportWorldEnemyNavigation>
    {protected override async ETTask Run(Session session,C2G_ReportWorldEnemyNavigation q,G2C_ReportWorldEnemyNavigation p){GatePlayerProxy a=OnlineWorldGateHelper.Authenticated(session);if(a==null){p.Error=ErrorCode.ERR_OnlineSessionNotLoggedIn;return;}G2P_ReportWorldEnemyNavigation m=G2P_ReportWorldEnemyNavigation.Create();m.PlayerId=a.PlayerId;m.SessionEpoch=a.SessionEpoch;m.NavigationLeaseRevision=q.NavigationLeaseRevision;m.ReportSequence=q.ReportSequence;foreach(WorldEnemyNavigationReport x in q.Reports)m.Reports.Add(CloneReport(x));using P2G_ReportWorldEnemyNavigation r=await session.Root().GetComponent<MessageSender>().Call(a.PlayerActorId,m,false) as P2G_ReportWorldEnemyNavigation;p.Error=r.Error;p.Message=r.Message;p.Accepted=r.Accepted;p.CurrentLeaseRevision=r.CurrentLeaseRevision;p.LastAcceptedReportSequence=r.LastAcceptedReportSequence;p.WorldRevision=r.WorldRevision;}private static WorldEnemyNavigationReport CloneReport(WorldEnemyNavigationReport s){WorldEnemyNavigationReport t=WorldEnemyNavigationReport.Create();t.UnitId=s.UnitId;t.LifecycleRevision=s.LifecycleRevision;t.PositionX=s.PositionX;t.PositionY=s.PositionY;t.PositionZ=s.PositionZ;t.YawDegrees=s.YawDegrees;return t;}}

